    .grid { display: grid; grid-template-columns: 1fr; gap: 14px; }

    .chart-card { padding: 18px 18px 16px; }
    .chart-title { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin-bottom: 10px; }
    .chart-title h2 { font-size: 16px; }
    .chart-title .meta { font-size: 12px; color: var(--text-secondary); }

    .canvas-wrap { height: 560px; }
    canvas { width: 100% !important; height: 100% !important; }

    .legend-inline { display: flex; flex-wrap: wrap; gap: 10px 12px; margin-top: 10px; }
    .legend-chip { display: inline-flex; align-items: center; gap: 8px; font-size: 12px; color: var(--text-secondary); }
    .swatch { width: 10px; height: 10px; border-radius: 3px; background: var(--accent); }

