    }
    h1 { font-weight: 750; }
    h2 { font-weight: 650; }
    body, p, li, td, th, span, label { font-weight: 400; }
    p,li,td,th,span,label { color: var(--text); }
    .text-secondary { color: var(--text-secondary); }

    .card {
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 12px; padding: 22px;
      transition: box-shadow 0.2s ease, transform 0.2s ease;
    }
    .card:hover {
      box-shadow: 0 0 0 1px var(--border), 0 10px 20px rgba(0,0,0,0.18);
      transform: translateY(-1px);
    }

    @keyframes fadeInUp {
      from { opacity: 0; transform: translateY(24px); }
      to { opacity: 1; transform: translateY(0); }
    }
    .animate { animation: fadeInUp 0.6s ease-out both; }
    .animate.delay-1 { animation-delay: 0.1s; }
    .animate.delay-2 { animation-delay: 0.2s; }
    .animate.delay-3 { animation-delay: 0.3s; }

    .reveal { opacity: 0; transform: translateY(24px); transition: opacity 0.6s ease, transform 0.6s ease; }
    .reveal.visible { opacity: 1; transform: translateY(0); }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation: none !important; transition: none !important; }
      .reveal { opacity: 1; transform: none; }
    }

    @media print {
      body { background: white !important; color: black !important; }
      .viz-menu, .reveal { display: revert; opacity: 1 !important; transform: none !important; }
      .card { break-inside: avoid; border: 1px solid #ddd; box-shadow: none; }
      * { print-color-adjust: exact; -webkit-print-color-adjust: exact; }
    }
    @page { margin: 1in; @bottom-center { content: "Page " counter(page); font-size: 9pt; color: #666; } }

    .viz-menu { position: fixed; top: 16px; right: 16px; z-index: 9999; }
    .viz-menu-toggle {
      width: 44px; height: 44px; border-radius: 12px;
      background: var(--surface); border: 1px solid var(--border);
      color: var(--text); cursor: pointer; display: flex;
      align-items: center; justify-content: center;
      backdrop-filter: blur(12px); transition: all 0.2s;
    }
    .viz-menu-toggle:hover { background: var(--surface-hover); }
    .viz-menu-dropdown {
      position: absolute; top: 52px; right: 0; min-width: 200px;
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 12px; padding: 8px;
      opacity: 0; visibility: hidden; transform: translateY(-8px);
      transition: all 0.2s; backdrop-filter: blur(16px);
    }
    .viz-menu-dropdown.open { opacity: 1; visibility: visible; transform: translateY(0); }
    .viz-menu-dropdown button {
      width: 100%; padding: 10px 14px; border: none; border-radius: 8px;
      background: transparent; color: var(--text); font-size: 14px;
      font-family: inherit; cursor: pointer; text-align: left;
      display: flex; align-items: center; gap: 10px; transition: background 0.15s;
    }
    .viz-menu-dropdown button:hover { background: var(--surface-hover); }

    .skip-to-content {
      position: absolute; top: -40px; left: 6px; background: var(--accent);
      color: white; padding: 8px 12px; text-decoration: none;
      border-radius: 4px; opacity: 0; pointer-events: none;
      transition: all 0.2s; z-index: 10000;
    }
    .skip-to-content:focus { top: 6px; opacity: 1; pointer-events: auto; }

    /* ===== Custom layout ===== */
    .wrap { max-width: 1120px; margin: 0 auto; padding: 34px 22px 40px; }
    header.hero { display: grid; grid-template-columns: 1.2fr 0.8fr; gap: 16px; align-items: end; margin-bottom: 18px; }
    .kicker { color: var(--text-secondary); font-size: 12px; letter-spacing: 0.08em; text-transform: uppercase; }
    .headline { font-size: 30px; line-height: 1.06; }
    .subhead { margin-top: 10px; color: var(--text-secondary); font-size: 14px; }
    .callouts { display: grid; gap: 10px; }
    .pill {
      border: 1px solid var(--border);
      background: linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0));
      border-radius: 12px;
      padding: 12px 14px;
    }
    .pill .label { font-size: 12px; color: var(--text-secondary); }
    .pill .value { font-size: 18px; font-weight: 650; margin-top: 2px; }
    .pill .note { font-size: 12px; color: var(--text-secondary); margin-top: 2px; }

    .grid { display: grid; grid-template-columns: 1fr; gap: 14px; }

    .chart-card { padding: 18px 18px 16px; }
    .chart-title { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; margin-bottom: 10px; }
    .chart-title h2 { font-size: 16px; }
    .chart-title .meta { font-size: 12px; color: var(--text-secondary); }

    .canvas-wrap { height: 560px; }
    canvas { width: 100% !important; height: 100% !important; }

    .legend-inline { display: flex; flex-wrap: wrap; gap: 10px 12px; margin-top: 10px; }
    .legend-chip { display: inline-flex; align-items: center; gap: 8px; font-size: 12px; color: var(--text-secondary); }
    .swatch { width: 10px; height: 10px; border-radius: 3px; background: var(--accent); }

    .foot { margin-top: 10px; font-size: 12px; color: var(--text-secondary); }

    @media (max-width: 900px) {
      header.hero { grid-template-columns: 1fr; }
      .canvas-wrap { height: 660px; }
    }
  </style>
</head>
<body>
  <a href="#main-content" class="skip-link" style="position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;z-index:10000;padding:8px 16px;background:var(--accent);color:white;text-decoration:none;border-radius:4px;" onfocus="this.style.cssText='position:fixed;left:16px;top:16px;z-index:10000;padding:8px 16px;background:var(--accent);color:white;text-decoration:none;border-radius:4px;'" onblur="this.style.cssText='position:absolute;left:-9999px;top:auto;width:1px;height:1px;overflow:hidden;'">Skip to content</a>
  <main id="main-content">

  <div class="viz-menu">
    <button class="viz-menu-toggle" onclick="toggleMenu()" aria-label="Menu">
      <svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round">
        <line x1="3" y1="5" x2="17" y2="5"/><line x1="3" y1="10" x2="17" y2="10"/><line x1="3" y1="15" x2="17" y2="15"/>
      </svg>
    </button>
    <div class="viz-menu-dropdown" id="vizMenuDropdown">
      <button onclick="cycleTheme()"><span id="themeIcon">🌙</span><span id="themeLabel">Dark</span></button>
      <button onclick="downloadImage()"><span>📥</span><span>Download PNG</span></button>
      <button onclick="window.print()"><span>🖨️</span><span>Print / PDF</span></button>
    </div>
  </div>

  <a href="#main-content" class="skip-to-content">Skip to content</a>

  <main id="main-content" role="main">
    <section class="wrap">
      <header class="hero animate">
        <div>
          <div class="kicker">AI Evolution · 2010–2025</div>
          <h1 class="headline">Three-track timeline: Research → Industry → Regulation</h1>
          <p class="subhead">Milestones are plotted by date across three parallel tracks. Point size reflects significance (medium / high / critical). The investment series (right axis) shows global private AI investment (USD billions).</p>
        </div>
        <div class="callouts">
          <div class="pill">
            <div class="label">Research → Industry lag</div>
            <div class="value">5.4 years</div>
            <div class="note">Transformer (2017-06) → ChatGPT (2022-11)</div>
          </div>
          <div class="pill">
            <div class="label">Industry → Regulation lag</div>
            <div class="value">1.3 years</div>
            <div class="note">ChatGPT (2022-11) → EU AI Act enacted (2024-03)</div>
          </div>
          <div class="pill">
            <div class="label">Investment jump</div>
            <div class="value">$48.2B → $95.8B</div>
            <div class="note">2022 to 2024 (≈2×) after ChatGPT</div>
          </div>
        </div>
      </header>

      <div class="grid">
        <section class="card chart-card" data-reveal>
          <div class="chart-title">
            <h2>Milestones across three tracks (with investment overlay)</h2>
            <div class="meta">X-axis: year · Left axis: track · Right axis: USD (billions)</div>
          </div>
          <div class="canvas-wrap">
            <canvas id="timelineChart" role="img" aria-label="Timeline chart showing research, industry, and regulation milestones from 2010 to 2025 with an overlay line for global private AI investment in USD billions."></canvas>
          </div>
          <div class="legend-inline" aria-label="Legend">
            <span class="legend-chip"><span class="swatch" style="background:#60A5FA"></span>Research milestones</span>
            <span class="legend-chip"><span class="swatch" style="background:#34D399"></span>Industry milestones</span>
            <span class="legend-chip"><span class="swatch" style="background:#FBBF24"></span>Regulation milestones</span>
            <span class="legend-chip"><span class="swatch" style="background:#A78BFA"></span>AI investment (USD B)</span>
          </div>
          <div class="foot">Source: `/app/benchmark/source_data.json` (milestones + annual investment). Dates are monthly for milestones and annual for investment.</div>
        </section>
      </div>
    </section>
  </main>

  </main>
  <script>
    function toggleMenu() { 
      var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
      if (dropdown) dropdown.classList.toggle('open'); 
    }
    document.addEventListener('click', function(e) { 
      if (!e.target.closest('.viz-menu')) {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });
    document.addEventListener('keydown', function(e) { 
      if (e.key === 'Escape') {
        var dropdown = document.getElementById('vizMenuDropdown') || document.getElementById('vizMenu');
        if (dropdown) dropdown.classList.remove('open');
      }
    });

    var savedTheme = localStorage.getItem('viz-theme');
    var currentTheme = savedTheme || (window.matchMedia('(prefers-color-scheme: light)').matches ? 'light' : 'dark');
    function applyTheme(t) {
      document.documentElement.className = 'theme-' + t;
      document.getElementById('themeIcon').textContent = t === 'dark' ? '🌙' : '☀️';
      document.getElementById('themeLabel').textContent = t === 'dark' ? 'Dark' : 'Light';
      localStorage.setItem('viz-theme', t);
      currentTheme = t;
      if (typeof onThemeChange === 'function') onThemeChange();
    }
    function cycleTheme() { applyTheme(currentTheme === 'dark' ? 'light' : 'dark'); }
    applyTheme(currentTheme);

    document.querySelectorAll('[data-reveal]').forEach(function(el){ el.classList.add('reveal'); });
    var revealObserver = new IntersectionObserver(function(entries) {
      entries.forEach(function(e) { if (e.isIntersecting) { e.target.classList.add('visible'); revealObserver.unobserve(e.target); } });
    }, { threshold: 0.15 });
    document.querySelectorAll('.reveal').forEach(function(el){ revealObserver.observe(el); });

    var ChartManager = {
      charts: new Map(),
      safeInit: function(canvasId, config) {
        if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return null; }
        try {
          if (this.charts.has(canvasId)) {
            this.charts.get(canvasId).destroy();
            this.charts.delete(canvasId);
          }
          var canvas = document.getElementById(canvasId);
          if (!canvas) { console.error('Canvas element not found: ' + canvasId); return null; }
          if (canvas.chart) { canvas.chart.destroy(); delete canvas.chart; }
          canvas.setAttribute('role', 'img');
          if (!canvas.getAttribute('aria-label')) canvas.setAttribute('aria-label', 'Chart visualization');
          var chart = new Chart(canvas, config);
          canvas.chart = chart;
          this.charts.set(canvasId, chart);
          return chart;
        } catch (e) {
          console.error('Chart init failed for ' + canvasId + ':', e);
          return null;
        }
      }
    };

    var sourceData = null;
    var chartsBuilt = false;

    function parseMonthToX(dateStr) {
      // dateStr: YYYY-MM
      var parts = String(dateStr).split('-');
      var y = parseInt(parts[0], 10);
      var m = parseInt(parts[1], 10);
      // place at mid-month fraction
      return y + ((m - 0.5) / 12.0);
    }

    function sizeBySignificance(sig) {
      if (sig === 'critical') return 10;
      if (sig === 'high') return 7;
      return 5;
    }

    function buildDatasets(isDark) {
      var researchColor = isDark ? '#60A5FA' : '#2563EB';
      var industryColor = isDark ? '#34D399' : '#059669';
      var regulationColor = isDark ? '#FBBF24' : '#D97706';
      var investColor = isDark ? '#A78BFA' : '#7C3AED';

      var tracks = [
        { key: 'research_milestones', y: 2, label: 'Research', color: researchColor },
        { key: 'industry_milestones', y: 1, label: 'Industry', color: industryColor },
        { key: 'regulation_milestones', y: 0, label: 'Regulation', color: regulationColor }
      ];

      var datasets = [];

      tracks.forEach(function(t) {
        var points = (sourceData[t.key].data || []).map(function(d) {
          return {
            x: parseMonthToX(d.date),
            y: t.y,
            r: sizeBySignificance(d.significance),
            label: d.label,
            date: d.date,
            significance: d.significance,
            detail: d.detail,
            track: t.label
          };
        });
        datasets.push({
          type: 'bubble',
          label: t.label + ' milestones',
          data: points,
          backgroundColor: t.color,
          borderColor: isDark ? 'rgba(0,0,0,0.35)' : 'rgba(255,255,255,0.9)',
          borderWidth: 1,
          hoverBorderWidth: 1,
          yAxisID: 'yTracks',
          parsing: false
        });
      });

      var investPoints = (sourceData.ai_investment.data || []).map(function(d) {
        return { x: d.year + 0.5, y: d.investment, year: d.year, investment: d.investment };
      });

      datasets.push({
        type: 'line',
        label: 'AI investment (USD B)',
        data: investPoints,
        parsing: false,
        xAxisID: 'x',
        yAxisID: 'yInvest',
        tension: 0.25,
        borderColor: investColor,
        backgroundColor: investColor,
        pointRadius: 3,
        pointHoverRadius: 5,
        borderWidth: 2,
        fill: false
      });

      return datasets;
    }

    function buildChart() {
      if (chartsBuilt) return;
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      if (!sourceData) { console.error('Data missing'); return; }

      var isDark = document.documentElement.classList.contains('theme-dark');
      var textColor = isDark ? '#EDEDED' : '#111827';
      var gridColor = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(17,24,39,0.10)';
      var borderColor = isDark ? 'rgba(255,255,255,0.14)' : 'rgba(0,0,0,0.10)';

      var annotationDates = [
        { key: 'Transformer architecture', date: '2017-06', track: 'Research', color: isDark ? '#60A5FA' : '#2563EB' },
        { key: 'ChatGPT launches', date: '2022-11', track: 'Industry', color: isDark ? '#34D399' : '#059669' },
        { key: 'EU AI Act enacted', date: '2024-03', track: 'Regulation', color: isDark ? '#FBBF24' : '#D97706' }
      ];

      function pointLabelPlugin() {
        return {
          id: 'pointLabels',
          afterDatasetsDraw: function(chart, args, pluginOptions) {
            var ctx = chart.ctx;
            ctx.save();
            ctx.font = '600 11px Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif';
            ctx.fillStyle = textColor;
            ctx.textBaseline = 'middle';

            annotationDates.forEach(function(a) {
              var x = parseMonthToX(a.date);
              var xp = chart.scales.x.getPixelForValue(x);
              var yv = (a.track === 'Research') ? 2 : (a.track === 'Industry' ? 1 : 0);
              var yp = chart.scales.yTracks.getPixelForValue(yv);
              // Find nearest point radius for background chip sizing (approx)
              var padX = 6, padY = 4;
              var label = a.key;
              var w = ctx.measureText(label).width;

              var chipX = xp + 10;
              var chipY = yp - 14;

              // Background chip
              ctx.globalAlpha = isDark ? 0.92 : 0.95;
              ctx.fillStyle = isDark ? 'rgba(20,20,20,0.9)' : 'rgba(255,255,255,0.92)';
              ctx.strokeStyle = borderColor;
              ctx.lineWidth = 1;
              roundRect(ctx, chipX, chipY, w + padX*2, 22, 8);
              ctx.fill();
              ctx.stroke();

              // Accent dot
              ctx.fillStyle = a.color;
              ctx.globalAlpha = 1;
              ctx.beginPath();
              ctx.arc(chipX + 10, chipY + 11, 3.2, 0, Math.PI*2);
              ctx.fill();

              // Text
              ctx.fillStyle = textColor;
              ctx.fillText(label, chipX + 18, chipY + 11);
            });

            // Lag arrows
            var x1 = parseMonthToX('2017-06');
            var x2 = parseMonthToX('2022-11');
            var x3 = parseMonthToX('2024-03');

            drawArrow(chart, x1, 2, x2, 1, isDark ? '#9CA3AF' : '#6B7280', '5.4y');
            drawArrow(chart, x2, 1, x3, 0, isDark ? '#9CA3AF' : '#6B7280', '1.3y');

            ctx.restore();
          }
        };
      }

      function roundRect(ctx, x, y, w, h, r) {
        var radius = Math.min(r, w/2, h/2);
        ctx.beginPath();
        ctx.moveTo(x + radius, y);
        ctx.arcTo(x + w, y, x + w, y + h, radius);
        ctx.arcTo(x + w, y + h, x, y + h, radius);
        ctx.arcTo(x, y + h, x, y, radius);
        ctx.arcTo(x, y, x + w, y, radius);
        ctx.closePath();
      }

      function drawArrow(chart, xFrom, yFrom, xTo, yTo, color, label) {
        var ctx = chart.ctx;
        var sx = chart.scales.x.getPixelForValue(xFrom);
        var sy = chart.scales.yTracks.getPixelForValue(yFrom);
        var ex = chart.scales.x.getPixelForValue(xTo);
        var ey = chart.scales.yTracks.getPixelForValue(yTo);

        // Offset slightly to avoid overdraw
        sx += 2; sy += 10;
        ex -= 2; ey -= 10;

        ctx.save();
        ctx.strokeStyle = color;
        ctx.fillStyle = color;
        ctx.lineWidth = 1.5;
        ctx.setLineDash([4, 4]);
        ctx.beginPath();
        ctx.moveTo(sx, sy);
        ctx.lineTo(ex, ey);
        ctx.stroke();
        ctx.setLineDash([]);

        // Arrow head
        var angle = Math.atan2(ey - sy, ex - sx);
        var headlen = 8;
        ctx.beginPath();
        ctx.moveTo(ex, ey);
        ctx.lineTo(ex - headlen * Math.cos(angle - Math.PI/6), ey - headlen * Math.sin(angle - Math.PI/6));
        ctx.lineTo(ex - headlen * Math.cos(angle + Math.PI/6), ey - headlen * Math.sin(angle + Math.PI/6));
        ctx.closePath();
        ctx.fill();

        // Label
        ctx.font = '700 11px Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif';
        ctx.fillStyle = color;
        var mx = (sx + ex) / 2;
        var my = (sy + ey) / 2;
        ctx.fillText(label, mx + 6, my - 8);
        ctx.restore();
      }

      var config = {
        type: 'bubble',
        data: {
          datasets: buildDatasets(isDark)
        },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          interaction: { mode: 'nearest', intersect: false },
          plugins: {
            tooltip: {
              enabled: true,
              callbacks: {
                title: function(items) {
                  var it = items && items[0];
                  if (!it) return '';
                  var raw = it.raw || {};
                  if (raw.track) return raw.track + ' · ' + (raw.date || '');
                  if (raw.year) return 'Investment · ' + raw.year;
                  return '';
                },
                label: function(item) {
                  var raw = item.raw || {};
                  if (raw.label) {
                    var sig = raw.significance ? (' (' + raw.significance + ')') : '';
                    return raw.label + sig;
                  }
                  if (typeof raw.investment === 'number') return 'USD ' + raw.investment.toFixed(1) + 'B';
                  return '';
                },
                afterLabel: function(item) {
                  var raw = item.raw || {};
                  if (raw.detail) return raw.detail;
                  return '';
                }
              }
            },
            legend: {
              display: false
            }
          },
          scales: {
            x: {
              type: 'linear',
              min: 2010,
              max: 2025.99,
              title: { display: true, text: 'Year', color: textColor, font: { weight: '600' } },
              ticks: {
                color: textColor,
                stepSize: 1,
                callback: function(val) { return String(Math.round(val)); }
              },
              grid: { color: gridColor },
              border: { color: borderColor }
            },
            yTracks: {
              type: 'linear',
              min: -0.6,
              max: 2.6,
              position: 'left',
              title: { display: true, text: 'Track', color: textColor, font: { weight: '600' } },
              ticks: {
                color: textColor,
                stepSize: 1,
                callback: function(value) {
                  if (value === 2) return 'Research';
                  if (value === 1) return 'Industry';
                  if (value === 0) return 'Regulation';
                  return '';
                }
              },
              grid: { color: gridColor },
              border: { color: borderColor }
            },
            yInvest: {
              type: 'linear',
              position: 'right',
              title: { display: true, text: 'Global private AI investment (USD billions)', color: textColor, font: { weight: '600' } },
              ticks: {
                color: textColor,
                callback: function(val) { return '$' + val; }
              },
              grid: { drawOnChartArea: false },
              border: { color: borderColor }
            }
          }
        },
        plugins: [pointLabelPlugin()]
      };

      ChartManager.safeInit('timelineChart', config);
      chartsBuilt = true;
    }

    function onThemeChange() {
      chartsBuilt = false;
      buildChart();
    }

    function ensureDataAndBuild() {
      if (sourceData) { buildChart(); return; }
      fetch('/app/benchmark/source_data.json')
        .then(function(r){ return r.json(); })
        .then(function(j){ sourceData = j; buildChart(); })
        .catch(function(e){ console.error('Failed to load data:', e); });
    }

    window.addEventListener('load', function(){
      ensureDataAndBuild();
      // For render pipelines that snapshot quickly
      setTimeout(buildChart, 200);
      setTimeout(buildChart, 800);
    });

    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      if (menu) menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, { quality: 1, pixelRatio: 2, filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); } });
        var a = document.createElement('a'); a.href = url;
        a.download = document.title.replace(/\s+/g, '-').toLowerCase() + '.png'; a.click();
      } catch(e) { console.error('Download failed:', e); }
      if (menu) menu.style.display = '';
    }
  </script>
</body>
</html>
